/** Receive confirmation is the split workflow; no dispatch or arrival screens. */
type RPC=(path:string,body?:unknown,timeout?:number)=>Promise<any>;
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
export class ReceivingWorkflow{
 private dialog:HTMLDialogElement;private data:any;private busy=false;private splitTouched=new Set<number>();private page=0;private fields=new Map<string,string>();private draftVersion=0;private actor=0;private writable=true;
 constructor(private api:RPC,private changed?:()=>Promise<void>){this.dialog=document.createElement('dialog');this.dialog.id='receiving-dialog';this.dialog.className='submission-dialog quotation-dialog';document.body.append(this.dialog);this.dialog.addEventListener('cancel',e=>{if(this.busy)e.preventDefault();});}
 private el<T extends HTMLElement=HTMLElement>(s:string){return this.dialog.querySelector<T>(s)!;}
 private async run(action:()=>Promise<void>){if(this.busy)return;this.busy=true;this.dialog.querySelectorAll<HTMLButtonElement|HTMLInputElement>('button,input').forEach(e=>{if(!e.disabled){e.dataset.locked='1';e.disabled=true;}});try{await action();}catch(error){const e=this.el('#receiving-error');if(e)e.textContent=(error as Error).message;}finally{this.busy=false;this.dialog.querySelectorAll<HTMLButtonElement|HTMLInputElement>('[data-locked]').forEach(e=>{e.disabled=false;delete e.dataset.locked;});}}
 private key(){return 'v7-receiving-command:'+this.actor;}
 async open(po:number){const ctx=await this.api('/api/receiving/context');this.actor=ctx.actor_id;this.writable=ctx.enabled;await this.recover();try{this.data=await this.api('/api/receiving/orders/'+po);}catch(error){if(![404,422].includes((error as Error&{status?:number}).status||0)||!this.writable)throw error;this.data=await this.api('/api/receiving/orders/'+po+'/open',{});}this.page=0;this.fields.clear();this.splitTouched.clear();const draft=await this.api('/api/receiving/orders/'+po+'/draft');this.draftVersion=draft.version;if(draft.base_version===this.data.version){this.fields=new Map(draft.payload?.fields||[]);this.splitTouched=new Set(draft.payload?.split_touched||[]);}this.render(false);}
 private fieldKey(e:HTMLInputElement){return e.dataset.good?'good:'+e.dataset.good:e.dataset.damaged?'damaged:'+e.dataset.damaged:e.dataset.split?'split:'+e.dataset.split+':'+e.dataset.store:e.id;}
 private capture(){this.dialog.querySelectorAll<HTMLInputElement>('input:not([type=checkbox])').forEach(e=>this.fields.set(this.fieldKey(e),e.value));}
 private render(preserve=true){if(preserve)this.capture();const p=this.data,central=p.snapshot.central,stores=p.snapshot.stores,lines=p.lines.slice(this.page*100,this.page*100+100);this.dialog.innerHTML=`<form method="dialog"><div class="dialog-heading"><h2>Receive · PO #${p.purchase_order_id} · HWY 99</h2><button aria-label="Close receiving">×</button></div><div class="dialog-body"><p>Confirm individual units physically received at HWY 99. Existing store allocations determine the split. Inventory movements start on Save &amp; Submit; failures stay visible for reconciliation.</p><p><b>All quantities below are individual units.</b> Pack sizes are shown for reference.</p><div class="submission-lines"><table class="receiving-table"><thead><tr><th>Product / variation</th><th>Ordered units</th><th>Previously received</th><th>Receiving now</th><th>Damaged now</th>${stores.map((s:any)=>`<th title="${esc(s.name)}">${esc(s.name)} · split units</th>`).join('')}<th>Remaining supplier units</th><th>Receipt variance</th><th>Receipt / inventory state</th></tr></thead><tbody>${lines.map((l:any)=>`<tr data-line="${l.id}"><td><b>${esc(l.item_name)}</b><br>${esc(l.variation_name)}<br><small>${esc(l.sku)} · ${l.pack_size} units/pack</small></td><td>${l.ordered_qty}</td><td>${l.received_good} good · ${l.received_damaged} quarantined${l.unassigned?`<br><b>${l.unassigned} held for owner split</b>`:''}</td><td><input data-good="${l.id}" type="number" min="0" step="1" placeholder="Unanswered" aria-label="Receiving now ${esc(l.sku)}"><small data-split-state="${l.id}"></small></td><td><input data-damaged="${l.id}" type="number" min="0" step="1" value="0" aria-label="Damaged now ${esc(l.sku)}"></td>${stores.map((s:any)=>`<td><small>Ordered ${l.ordered[s.id]}${l.reallocated[s.id]?` · revised ${l.ordered[s.id]+l.overage[s.id]+l.reallocated[s.id]}`:''} · assigned ${l.allocated[s.id]} · closed ${l.closed[s.id]}</small><input data-split="${l.id}" data-store="${s.id}" type="number" min="0" step="1" value="${l.remaining[s.id]}" ${p.owner?'':'readonly'} aria-label="${esc(s.name)} split ${esc(l.sku)}"></td>`).join('')}<td data-remaining="${l.id}">${l.supplier_outstanding}</td><td data-variance="${l.id}">—</td><td>${esc(l.status)}<br>${l.posting.filter((x:any)=>x.state==='VERIFIED').length}/${l.posting.length} inventory movements verified</td></tr>`).join('')}</tbody></table></div><p>${p.owner?'Full receipts use the saved split. For a shortage, adjust only the store quantities that change. Held partial receipts can be split here without entering a new receipt.':'Partial receipts are recorded at HWY 99 and held for the owner-approved split. No store priority is inferred.'}</p><div class="receiving-actions"><button type="button" id="receiving-fill">Copy outstanding quantities for review</button><button type="button" id="receiving-prev" ${this.page?'':'disabled'}>Previous 100</button><span>Viewing ${this.page*100+1}–${this.page*100+lines.length} of ${p.lines.length}</span><button type="button" id="receiving-next" ${(this.page+1)*100<p.lines.length?'':'disabled'}>Next 100</button></div><label>Receipt / discrepancy notes (optional for normal receipts)<input id="receiving-reason" placeholder="Delivery reference and observed exceptions"></label><label class="authorization-ack"><input id="receiving-confirm" type="checkbox">I confirm the actual quantities received at HWY 99 and the reviewed store split.</label>${p.owner?`<details class="receiving-exceptions"><summary>Owner receiving exceptions and commercial closure</summary><p>Original ordered quantities and financial records remain unchanged. Corrections require a verified physical event.</p><label>PO line<select id="receiving-exception-line">${p.lines.map((l:any)=>`<option value="${l.id}">${esc(l.item_name)} · ${esc(l.variation_name)} · ${esc(l.sku)}</option>`).join('')}</select></label><label>Owner action<select id="receiving-exception-action"><option value="CLOSE">Close Remaining for selected stores</option><option value="OVERAGE">Approve supplier overage and separate valuation</option><option value="RESOLVE">Resolve damaged supplier discrepancy</option><option value="DISCREPANCY">Record incorrect product / discrepancy</option><option value="CORRECTION">Record physical correction</option></select></label><div>${stores.map((s:any)=>`<label>${esc(s.name)} · exception units<input data-exception-store="${s.id}" type="number" min="0" step="1" value="0"></label>`).join('')}</div><label>Separate approved overage total USD<input id="receiving-overage-value" placeholder="Explicit cents; no inferred value"></label><label>Exception / damaged / correction units<input id="receiving-exception-units" type="number" min="0" step="1" placeholder="Unanswered"></label><label>Correction source<select id="receiving-correction-source"><option value="CENTRAL_UNASSIGNED">Unassigned stock at HWY 99</option><option value="CENTRAL_AVAILABLE">HWY 99 stock retained locally</option><option value="CENTRAL_QUARANTINE">Quarantined stock at HWY 99</option><option value="DESTINATION_AVAILABLE">Inventory posted to a destination store</option></select></label><label>Correction store<select id="receiving-correction-store"><option value="">Unassigned / central quarantine</option>${stores.map((s:any)=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>Correct destination (store split corrections only)<select id="receiving-correction-destination">${stores.map((s:any)=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>Verified physical correction<select id="receiving-correction-disposition"><option value="RETURN_FOR_REPLACEMENT">Supplier return for replacement; reopen supplier balance</option><option value="REALLOCATE_POSTED">Correct a posted store split without changing the PO total</option><option value="INTERNAL_LOSS">Verified internal loss; preserve supplier fulfillment</option><option value="RECEIPT_COUNT_CORRECTION">Correct an overstated receipt from verified physical evidence</option></select></label><label>Observed incorrect product (description only)<input id="receiving-observed-product"></label><label>Owner evidence and valuation / closure explanation<input id="receiving-exception-evidence"></label><label><input id="receiving-exception-confirm" type="checkbox">I explicitly authorize this exception and its quantity / valuation consequences.</label><button type="button" id="receiving-exception-submit">Record reviewed owner exception</button></details>`:''}<button type="button" id="receiving-reconcile">Refresh / reconcile inventory movements</button><details><summary>Receipt and inventory history</summary>${p.lines.flatMap((l:any)=>l.discrepancies.filter((x:any)=>!x.complete).map((x:any)=>`<p>${esc(l.sku)} · ${esc(x.observed_product||'Unidentified delivery')} · ${x.units===null?'Quantity unknown':x.units-x.returned_units+' unresolved individual units'} · ${esc(x.description)} ${p.owner?`<button type="button" data-resolve-delivery="${x.event_id}" data-line-id="${l.id}" data-remaining-units="${x.units===null?'':x.units-x.returned_units}">Record verified supplier return</button>`:''}</p>`)).join('')}${p.history.map((e:any)=>`<p>${esc(e.created_at)} · ${esc(e.kind)} · ${esc(e.payload.reason)}</p>`).join('')||'<p>No submitted receipts.</p>'}${p.lines.flatMap((l:any)=>l.posting).filter((x:any)=>x.state!=='VERIFIED').map((x:any)=>`<p>${esc(x.id)} · ${esc(x.state)} · ${esc(x.evidence.detail||x.evidence.error||'Inventory movement awaits verified outcome')}${p.owner?` <button type="button" data-inventory-retry="${x.id}" data-interrupted="${x.state==='IN_FLIGHT'}">Review same-command recovery</button>`:''}</p>`).join('')}</details></div><p id="receiving-error" role="alert"></p><div class="dialog-footer"><button>Close</button><button type="button" id="receiving-save">Save</button><button type="button" class="primary" id="receiving-submit">Save &amp; Submit</button></div></form>`;
 this.dialog.querySelectorAll<HTMLInputElement>('input:not([type=checkbox])').forEach(e=>{const v=this.fields.get(this.fieldKey(e));if(v!==undefined)e.value=v;});if(!this.dialog.open)this.dialog.showModal();this.el('#receiving-fill').onclick=()=>{for(const l of lines)this.el<HTMLInputElement>(`[data-good="${l.id}"]`).value=l.supplier_outstanding?String(l.supplier_outstanding):'';this.recalculate();};this.el('#receiving-prev').onclick=()=>{this.page--;this.render();};this.el('#receiving-next').onclick=()=>{this.page++;this.render();};this.el('#receiving-submit').onclick=()=>void this.run(()=>this.submit());this.el('#receiving-save').onclick=()=>void this.run(()=>this.saveDraft());this.dialog.querySelectorAll<HTMLButtonElement>('[data-resolve-delivery]').forEach(b=>b.onclick=()=>void this.run(async()=>{const actual=prompt('Individual units physically returned to the supplier:');if(actual===null)return;if(!/^\d+$/.test(actual)||Number(actual)<=0)throw Error('Enter verified positive whole units.');const reason=prompt('Describe the verified physical return.');if(!reason)return;const intent={po:this.data.purchase_order_id,body:{command_id:crypto.randomUUID(),expected_version:this.data.version,kind:'RESOLVE',lines:[{line_id:Number(b.dataset.lineId),discrepancy_event_id:b.dataset.resolveDelivery,returned_units:Number(actual),physical_evidence:reason,complete:b.dataset.remainingUnits===''?confirm('Have all units associated with this delivery exception now been physically returned?'):Number(actual)===Number(b.dataset.remainingUnits)}],reason,confirmed:true}};if(localStorage.getItem(this.key()))throw Error('Recover the retained command first.');localStorage.setItem(this.key(),JSON.stringify(intent));await this.send(intent);}));this.dialog.querySelectorAll<HTMLButtonElement>('[data-inventory-retry]').forEach(b=>b.onclick=()=>void this.run(async()=>{const reason=prompt('Explain owner review of this inventory operation. Retry keeps its original identity and payload. If marked in flight, independently confirm the prior worker is stopped before proceeding.');if(!reason)return;await this.api('/api/receiving/inventory/'+b.dataset.inventoryRetry+'/retry',{reason,interrupted_worker_confirmed:b.dataset.interrupted==='true'},120000);this.data=await this.api('/api/receiving/orders/'+this.data.purchase_order_id);this.render();}));this.el('#receiving-reconcile').onclick=()=>void this.run(async()=>{await this.api('/api/receiving/orders/'+this.data.purchase_order_id+'/inventory',{},120000);this.data=await this.api('/api/receiving/orders/'+this.data.purchase_order_id);this.render();});this.el('#receiving-exception-submit')?.addEventListener('click',()=>void this.run(()=>this.exception()));this.dialog.querySelectorAll<HTMLInputElement>('[data-good],[data-damaged]').forEach(e=>e.oninput=()=>this.recalculate());this.dialog.querySelectorAll<HTMLInputElement>('[data-split]').forEach(e=>e.oninput=()=>{this.splitTouched.add(Number(e.dataset.split));this.recalculate();});this.recalculate();if(!this.writable||!p.capabilities.includes('ENTER')){this.dialog.querySelectorAll<HTMLInputElement>('[data-good],[data-damaged],[data-split],#receiving-reason,#receiving-confirm').forEach(e=>e.disabled=true);this.el<HTMLButtonElement>('#receiving-save').disabled=true;}if(!this.writable||!p.capabilities.includes('CONFIRM')||!p.capabilities.includes('ENTER'))this.el<HTMLButtonElement>('#receiving-submit').disabled=true;if(!this.writable){this.el<HTMLButtonElement>('#receiving-reconcile').disabled=true;this.el<HTMLButtonElement>('#receiving-exception-submit')?.setAttribute('disabled','');this.el('#receiving-error').textContent='New receiving is paused. Original receipt and inventory history remain available.';}}
 private recalculate(){for(const l of this.data.lines){const field=this.el<HTMLInputElement>(`[data-good="${l.id}"]`);if(!field)continue;const remaining=this.el(`[data-remaining="${l.id}"]`);remaining.textContent=field.value===''?String(l.supplier_outstanding):String(l.supplier_outstanding-Number(field.value));this.el(`[data-split-state="${l.id}"]`).textContent=field.value!==''&&Number(field.value)<l.supplier_outstanding&&!this.splitTouched.has(l.id)?'Partial receipt: held at HWY 99 until owner approves the split.':'';this.el(`[data-variance="${l.id}"]`).textContent=field.value===''?'—':String(Number(field.value)-l.supplier_outstanding);if(!this.splitTouched.has(l.id)){const full=field.value!==''&&Number(field.value)===l.supplier_outstanding&&!l.unassigned;for(const store of this.data.snapshot.stores)this.el<HTMLInputElement>(`[data-split="${l.id}"][data-store="${store.id}"]`).value=String(full||this.data.owner?l.remaining[store.id]:0);}}}
 private values(){this.capture();const lines:any[]=[];const kinds=new Set<string>();let allocating=false;for(const l of this.data.lines){const good={value:this.fields.get('good:'+l.id)||''},damaged={value:this.fields.get('damaged:'+l.id)||'0'};const touched=this.splitTouched.has(l.id);if(good.value===''&&!touched)continue;const integer=(v:string)=>{if(!/^\d+$/.test(v)||Number(v)>2147483647)throw Error('Enter whole nonnegative individual units. Blank means unanswered.');return Number(v);};const split=Object.fromEntries(Object.keys(l.ordered).map(k=>[k,integer(this.fields.get('split:'+l.id+':'+k)??String(l.remaining[k]))]));if(good.value===''&&l.unassigned&&touched){allocating=true;kinds.add('ALLOCATE');lines.push({line_id:l.id,split});}else{kinds.add('RECEIPT');if(allocating)throw Error('Approve held split separately from a new delivery in this same Receive confirmation.');lines.push({line_id:l.id,good:integer(good.value),damaged:integer(damaged.value),...(touched?{split}:{})});}}if(kinds.size>1)throw Error('Submit held splits and new deliveries as separate verified events using this same Receive confirmation.');if(!lines.length)throw Error('Enter actual received quantities or adjust a held partial split.');return {kind:allocating?'ALLOCATE':'RECEIPT',lines};}
 private async exception(){if(!this.el<HTMLInputElement>('#receiving-exception-confirm').checked)throw Error('Explicit owner exception approval is required.');const line=Number(this.el<HTMLSelectElement>('#receiving-exception-line').value),kind=this.el<HTMLSelectElement>('#receiving-exception-action').value,reason=this.el<HTMLInputElement>('#receiving-exception-evidence').value;const count=(s:string)=>{if(!/^\d+$/.test(s))throw Error('Whole nonnegative exception units required.');return Number(s);};const stores=Object.fromEntries([...this.dialog.querySelectorAll<HTMLInputElement>('[data-exception-store]')].map(e=>[e.dataset.exceptionStore!,count(e.value)]));let value:any={line_id:line};if(kind==='CLOSE')value.stores=stores;else if(kind==='OVERAGE')value={...value,stores,currency:'USD',approved_total:this.el<HTMLInputElement>('#receiving-overage-value').value,valuation_reason:reason};else if(kind==='RESOLVE')value={...value,acknowledged_damage:count(this.el<HTMLInputElement>('#receiving-exception-units').value),physical_evidence:reason};else if(kind==='DISCREPANCY'){const observed=this.el<HTMLInputElement>('#receiving-exception-units').value;value={...value,description:reason,units:observed===''?null:count(observed),observed_product:this.el<HTMLInputElement>('#receiving-observed-product').value};}else{const store=this.el<HTMLSelectElement>('#receiving-correction-store').value;value={...value,from_account:this.el<HTMLSelectElement>('#receiving-correction-source').value,store_id:store?Number(store):null,units:count(this.el<HTMLInputElement>('#receiving-exception-units').value),disposition:this.el<HTMLSelectElement>('#receiving-correction-disposition').value,physical_evidence:reason};if(value.disposition==='REALLOCATE_POSTED')value.to_store_id=Number(this.el<HTMLSelectElement>('#receiving-correction-destination').value);}const intent={po:this.data.purchase_order_id,body:{command_id:crypto.randomUUID(),expected_version:this.data.version,kind,lines:[value],reason,confirmed:true}};if(localStorage.getItem(this.key()))throw Error('Recover the retained command first.');localStorage.setItem(this.key(),JSON.stringify(intent));await this.send(intent);}
 private async saveDraft(){this.capture();const result=await this.api('/api/receiving/orders/'+this.data.purchase_order_id+'/draft',{expected_draft_version:this.draftVersion,base_version:this.data.version,payload:{fields:[...this.fields],split_touched:[...this.splitTouched]}});this.draftVersion=result.version;this.el('#receiving-error').textContent='Draft saved. No inventory movement or receipt was submitted.';}
 private async submit(){if(localStorage.getItem(this.key()))throw Error('Recover the retained receiving command before creating another receipt. Close and reopen Receive.');if(!this.el<HTMLInputElement>('#receiving-confirm').checked)throw Error('Confirm the physical receipt and reviewed split.');const decision=this.values(),intent={po:this.data.purchase_order_id,body:{command_id:crypto.randomUUID(),expected_version:this.data.version,...decision,reason:this.el<HTMLInputElement>('#receiving-reason').value.trim()||(decision.kind==='ALLOCATE'?'Owner reviewed the split of a previously verified HWY 99 receipt':'Physical receipt confirmed at HWY 99; approved store split reviewed'),confirmed:true}};localStorage.setItem(this.key(),JSON.stringify(intent));await this.send(intent);}
 private async send(intent:any){try{await this.api('/api/receiving/orders/'+intent.po+'/commands',intent.body,120000);}catch(error){try{await this.api('/api/receiving/commands/'+intent.body.command_id);}catch{if([409,422].includes((error as Error&{status?:number}).status||0)){localStorage.removeItem(this.key());throw error;}throw Error('Receipt outcome is not confirmed. The exact command is retained for recovery; do not submit another receipt. '+(error as Error).message);}}localStorage.removeItem(this.key());if(this.changed)await this.changed();this.data=await this.api('/api/receiving/orders/'+intent.po);for(let poll=0;poll<20&&this.data.lines.some((l:any)=>l.posting.some((x:any)=>x.state==='PENDING'||x.state==='IN_FLIGHT'));poll++){await new Promise(r=>setTimeout(r,150));this.data=await this.api('/api/receiving/orders/'+intent.po);}this.splitTouched.clear();this.fields.clear();this.render(false);this.el('#receiving-error').textContent='Receipt / split recorded. Inventory movements retain their individual verified or unresolved states.';}
 async recover(){const saved=localStorage.getItem(this.key());if(saved){const intent=JSON.parse(saved);try{await this.api('/api/receiving/commands/'+intent.body.command_id);localStorage.removeItem(this.key());}catch(error){if((error as Error&{status?:number}).status===404)await this.send(intent);else throw error;}}}
}
