/** Explicit two-stage owner review; no automatic authorization or delivery. */
import type {Snapshot} from './model.ts';
type RPC=(path:string,body?:unknown,timeout?:number)=>Promise<any>;
type Context={api:RPC;canAuthorize:()=>boolean;current:()=>Snapshot;ready:()=>Promise<void>;refresh:()=>Promise<void>;notify:(text:string,error?:boolean)=>void;quotation?:(id:string)=>Promise<void>;receive?:(id:number)=>Promise<void>};
const escape=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const find=<T extends HTMLElement=HTMLElement>(id:string)=>document.querySelector<T>('#'+id)!;
export class SubmissionWorkflow{
 private dialog:HTMLDialogElement;private selected:string[]=[];private review:any;private choices:Record<string,{source:string;unit_value:string;reason:string}>={};private currency='';private header={purchaser:'',ship_to:''};private incremental='';private page=0;private busy=false;
 constructor(private context:Context){this.dialog=document.createElement('dialog');this.dialog.id='submission-dialog';this.dialog.className='submission-dialog';document.body.append(this.dialog);}
 private open(title:string,content:string,action?:()=>Promise<void>,label='Continue'){
  if(this.dialog.open)this.dialog.close();this.dialog.innerHTML=`<form method="dialog"><div class="dialog-heading"><h2>${escape(title)}</h2><button class="close" value="cancel" aria-label="Close purchasing review">×</button></div><div class="dialog-body">${content}</div><p id="submission-error" role="alert"></p><div class="dialog-footer"><button value="cancel">Close</button>${action?`<button type="button" id="submission-next" class="primary">${escape(label)}</button>`:''}</div></form>`;this.dialog.showModal();if(action)find('submission-next').onclick=async()=>{if(this.busy)return;this.busy=true;find<HTMLButtonElement>('submission-next').disabled=true;try{await action();}catch(e){find('submission-error').textContent=(e as Error).message;}finally{this.busy=false;const button=find<HTMLButtonElement>('submission-next');if(button)button.disabled=false;}};
 }
 async start(ids:string[]){if(!this.context.canAuthorize())throw Error('New purchasing authorization is paused.');if(!ids.length)throw Error('Select vendors explicitly.');await this.context.ready();this.selected=[...ids];this.choices={};this.currency='';this.header={purchaser:'',ship_to:''};this.incremental='';this.page=0;await this.load();}
 private async load(previous?:string){const state=this.context.current();this.review=await this.context.api('/api/submission-reviews',{review_id:crypto.randomUUID(),session_id:state.session.id,expected_version:state.session.version,supplier_ids:this.selected,currency:this.currency||null,valuations:this.choices,incremental_reason:this.incremental,public_header:this.header,previous_review_id:previous});this.edit();}
 private summary(){const r=this.review,positive=r.lines.filter((l:any)=>l.total_packs>0),po=r.groups.filter((g:any)=>g.kind==='PO'),requests=r.groups.filter((g:any)=>g.kind==='REQUEST');return `<div class="submission-summary"><b>${r.groups.length} selected vendors · ${positive.length} positive product lines</b><span>${po.length} direct POs · ${requests.length} confirmation requests</span><span>${r.lines.filter((l:any)=>l.total_packs===0).length} zero rows remain editable · ${r.unresolved_quantity_lines} unresolved quantity rows require worksheet review · unselected vendors are excluded</span></div><p class="muted">Worksheet revision ${r.worksheet_version} · Pinned generation ${escape(r.generation_as_of)} · Incoming supply reviewed ${escape(r.reviewed_at)}. Orders are packs; inventory and incoming supply are individual units.</p><div class="submission-vendors">${r.groups.map((g:any)=>`<span><b>${escape(g.profile.name)}</b> · ${g.kind==='PO'?'Direct PO':'Request only; no commitment'} · ${g.positive_lines} lines${g.minimum_warning?'<small>'+escape(g.minimum_warning)+'</small>':''}</span>`).join('')}</div>`;}
 private edit(){const r=this.review,start=this.page*100,lines=r.lines.slice(start,start+100);this.open('Review selected purchasing',this.summary()+`<div class="submission-controls"><label>Valuation currency<select id="submission-currency"><option value="">Choose explicitly</option><option value="USD" ${this.currency==='USD'?'selected':''}>USD</option></select></label><label>Public purchaser name<input id="submission-purchaser" maxlength="200" value="${escape(this.header.purchaser)}" placeholder="Name to print on the vendor document"></label><label>Public shipping instructions<textarea id="submission-shipping" maxlength="2000" placeholder="Explicit vendor-facing destination/instructions">${escape(this.header.ship_to)}</textarea></label></div><button id="submission-use-expected" type="button">Use expected valuations for known, representable costs</button><p class="muted">Expected cost remains unchanged. Unknown costs require your explicit committed unit valuation and reason; zero is permitted only as an explicit approved valuation. Vendor quotations, invoices and payments remain separate. Confirmation requests create no financial commitment.</p><div class="submission-lines"><table><thead><tr><th>Product / variation</th><th>Pack</th>${r.stores.map((s:any)=>`<th title="${escape(s.name)} packs">${escape(s.name)}<br>packs</th>`).join('')}<th>Total<br>units</th><th>Expected<br>unit cost</th><th>Approved unit<br>valuation / source</th><th>Valuation reason</th><th>Incoming units<br>${r.stores.map((s:any)=>escape(s.name)).join(' / ')}</th><th>Supply overlap / recent changes</th></tr></thead><tbody>${lines.map((l:any)=>{const value=this.choices[l.row_id],needed=l.kind==='PO'&&l.total_packs>0;return `<tr data-review-row="${l.row_id}"><td><b>${escape(l.name)}</b><br>${escape(l.variation)}<small>${escape(r.groups.find((g:any)=>g.supplier_id===l.supplier_id).profile.name)} · ${l.total_packs===0?'Zero row retained':l.kind==='PO'?'Direct PO':'Request only'}</small></td><td class="numeric">${l.pack_size??'Unknown'}</td>${l.packs.map((p:any)=>`<td class="numeric">${p??'Unknown'}</td>`).join('')}<td class="numeric">${l.total_units??'Unknown'}</td><td class="numeric">${escape(l.expected_unit_cost??'Unknown')}</td><td>${needed?`<input data-unit="${l.row_id}" inputmode="decimal" value="${escape(value?.unit_value??'')}" aria-label="Committed unit valuation for ${escape(l.name+' '+l.variation)}"><select data-source="${l.row_id}" aria-label="Valuation source"><option value="">Choose source</option><option value="EXPECTED" ${value?.source==='EXPECTED'?'selected':''}>Expected, explicitly accepted</option><option value="OWNER_EXPLICIT" ${value?.source==='OWNER_EXPLICIT'?'selected':''}>Owner approved valuation</option></select>`:'No commitment'}</td><td>${needed?`<input data-reason="${l.row_id}" maxlength="2000" value="${escape(value?.reason??'')}" aria-label="Valuation reason">`:'—'}</td><td class="numeric">${l.incoming.join(' / ')}</td><td>${l.overlap.length?`<details class="overlap"><summary>${l.overlap.length} overlapping supply records</summary>${l.overlap.map((v:any)=>`<p>${escape(v.kind.replaceAll('_',' ').toLowerCase())}: ${escape(v.reference)} · store ${v.store_id??'unresolved'} · ${v.units??'unknown'} units</p>`).join('')}</details>`:'No outstanding overlap'}${l.warnings.length?`<details><summary>${l.warnings.length} evidence warnings</summary>${l.warnings.map((v:string)=>`<p>${escape(v.replaceAll('_',' ').toLowerCase())}</p>`).join('')}</details>`:''}</td></tr>`;}).join('')}</tbody></table></div><div class="submission-pagination"><button id="submission-prev" type="button" ${start===0?'disabled':''}>Previous 100</button><span>Viewing ${start+1}–${Math.min(start+100,r.lines.length)} of ${r.lines.length} selected rows. The final authorization covers the full reviewed selection.</span><button id="submission-more" type="button" ${start+100>=r.lines.length?'disabled':''}>Next 100</button></div><label class="incremental-label">Additional-purchase reason, required for overlapping supply, pending requests or purchasing changes since the pinned generation<textarea id="submission-incremental" maxlength="2000" placeholder="Explain the separately reviewed additional purchase">${escape(this.incremental)}</textarea></label><p id="submission-estimate">Expected internal subtotal ${escape(r.expected_known_subtotal)} ${escape(r.currency??'currency not chosen')} ${r.unknown_expected_cost_lines?' + '+r.unknown_expected_cost_lines+' unknown-cost lines':''}. Final committed totals are calculated by the server on the next review.</p>`,async()=>{this.capture();await this.loadExact();},'Review exact authorization');
 find('submission-use-expected').onclick=()=>{this.capture();for(const l of r.lines)if(l.kind==='PO'&&l.total_packs>0&&l.expected_unit_cost!==null&&/^\d+(\.\d{1,4})?$/.test(l.expected_unit_cost))this.choices[l.row_id]={source:'EXPECTED',unit_value:l.expected_unit_cost,reason:'Owner explicitly accepts the pinned expected cost as committed valuation'};this.edit();};find('submission-prev').onclick=()=>{this.capture();this.page--;this.edit();};find('submission-more').onclick=()=>{this.capture();this.page++;this.edit();};
 }
 private capture(){this.currency=find<HTMLSelectElement>('submission-currency').value;this.header={purchaser:find<HTMLInputElement>('submission-purchaser').value,ship_to:find<HTMLTextAreaElement>('submission-shipping').value};this.incremental=find<HTMLTextAreaElement>('submission-incremental').value;this.dialog.querySelectorAll<HTMLInputElement>('[data-unit]').forEach(input=>{const id=input.dataset.unit!,source=this.dialog.querySelector<HTMLSelectElement>(`[data-source="${id}"]`)!.value,reason=this.dialog.querySelector<HTMLInputElement>(`[data-reason="${id}"]`)!.value;if(input.value||source||reason)this.choices[id]={source,unit_value:input.value,reason};else delete this.choices[id];});}
 private async loadExact(){const state=this.context.current();const exact=await this.context.api('/api/submission-reviews',{review_id:crypto.randomUUID(),session_id:state.session.id,expected_version:state.session.version,supplier_ids:this.selected,currency:this.currency||null,valuations:this.choices,incremental_reason:this.incremental,public_header:this.header,previous_review_id:this.review.id});this.review=exact;if(exact.blocking.length){this.edit();find('submission-error').textContent=exact.blocking.slice(0,20).join(' · ');return;}this.confirm();}
 private confirm(){const r=this.review;this.open('Authorize exact reviewed purchasing',this.summary()+`<div class="exact-total"><b>Committed valuation: ${escape(r.committed_total)} ${escape(r.currency)}</b><span>Expected internal subtotal: ${escape(r.expected_known_subtotal)} ${escape(r.currency)}${r.unknown_expected_cost_lines?' + unknown expected costs':''}</span></div><p><b>Public purchaser:</b> ${escape(r.public_header.purchaser)}<br><b>Public shipping:</b> ${escape(r.public_header.ship_to)}</p><p>${r.incremental_reason?'<b>Incremental authorization:</b> '+escape(r.incremental_reason):'No overlapping purchasing supply was detected in this review.'}</p><div class="submission-lines"><table><thead><tr><th>Product / variation</th><th>Pack size</th><th>Store packs</th><th>Total packs</th><th>Total units</th><th>Approved unit valuation</th><th>Incoming units</th></tr></thead><tbody>${r.lines.slice(0,100).map((l:any)=>`<tr><td>${escape(l.name)}<br>${escape(l.variation)}</td><td>${l.pack_size??'Unknown'}</td><td>${l.packs.map((n:any)=>n??'Unknown').join(' / ')}</td><td>${l.total_packs??'Unknown'}</td><td>${l.total_units??'Unknown'}</td><td>${escape(l.valuation?.unit_value??'Request only; no commitment')}<br><small>${escape(l.valuation?.source??'')}</small></td><td>${l.incoming.join(' / ')}</td></tr>`).join('')}</tbody></table></div><p class="muted">${r.lines.length>100?'The first 100 rows are shown here; the complete immutable review includes '+r.lines.length+' rows. ':''}Store order: ${r.stores.map((s:any)=>escape(s.name)).join(' / ')}. No inventory will be posted and no vendor email will be sent. Vendor files contain consolidated packs and units, with no internal costs or store allocations.</p><button id="submission-back" type="button">Back to all reviewed products and valuations</button><label class="authorization-ack"><input id="authorization-ack" type="checkbox"> I authorize exactly these direct purchase orders and submit these selected confirmation requests, including the reviewed supply overlap and approved valuations.</label>`,async()=>{if(!find<HTMLInputElement>('authorization-ack').checked)throw Error('Explicit owner authorization is required.');const prior=this.pending().find(p=>p.review_id===r.id),intent=prior??{command_id:crypto.randomUUID(),review_id:r.id,acknowledged:true};localStorage.setItem(this.key(intent.command_id),JSON.stringify(intent));await this.submit(intent);},r.groups.every((g:any)=>g.kind==='REQUEST')?'Submit reviewed requests':'Authorize reviewed POs and submit requests');find('submission-back').onclick=()=>this.edit();}
 private key(command=''){return 'v5-authorization:'+this.context.current().session.owner_id+':'+command;}
 private pending():any[]{const prefix=this.key();return Object.keys(localStorage).filter(k=>k.startsWith(prefix)).map(k=>JSON.parse(localStorage.getItem(k)!));}
 private async submit(intent:any){let result;try{result=await this.context.api('/api/purchase-authorizations',intent,120000);}catch(error){const status=(error as Error&{status?:number}).status;if(status===409||status===422){try{const existing=await this.context.api('/api/authorization-commands/'+intent.command_id);if(existing.review_id===intent.review_id){result=existing;}}catch(lookup){if((lookup as Error&{status?:number}).status===404){localStorage.removeItem(this.key(intent.command_id));this.context.notify('Authorization was rejected without a committed receipt. Refresh and review the changed state. '+(error as Error).message,true);throw error;}}}if(!result){this.context.notify('Authorization outcome not confirmed. Recover this same command; do not create another purchasing decision. '+(error as Error).message,true);throw error;}}localStorage.removeItem(this.key(intent.command_id));try{await this.context.refresh();}catch(error){this.context.notify('Authorization is recorded. Worksheet refresh failed; reload before editing submitted rows. '+(error as Error).message,true);}this.result(result);}
 async recover(){for(const intent of this.pending()){try{let result;try{result=await this.context.api('/api/authorization-commands/'+intent.command_id);}catch(error){if((error as Error&{status?:number}).status!==404)throw error;if(!this.context.canAuthorize())throw Error('Authorization is paused; the previous command remains retained for reconciliation.');await this.submit(intent);continue;}localStorage.removeItem(this.key(intent.command_id));this.result(result);try{await this.context.refresh();}catch(error){this.context.notify('Recorded authorization recovered; refresh the worksheet before editing. '+(error as Error).message,true);}}catch(error){this.context.notify('Previous authorization retained for same-command recovery: '+(error as Error).message,true);}}}
 private result(r:any){this.open('Purchasing authorization recorded',`<p id="authorization-result"><b>${r.commitments_created} purchase orders authorized · ${r.requests_created} requests awaiting vendor response</b></p><p>${this.context.receive?'Purchasing authorization is recorded. Use Receive to confirm actual quantities at HWY 99 and initiate the approved inventory split. Financial assignments, invoices and payments retain their separate authority.':r.source_request_id?'Final quotation quantities and valuation are authorized. Original request rows remain sealed as history; final allocations and released remainder are in the quotation review. No inventory posting or real vendor delivery occurred.':"No inventory posting or real vendor delivery occurred. Authorized products are sealed; unselected and zero-quantity rows remain editable. Further purchases require a separately reviewed incremental decision. Financial assignments, invoices and payments retain their separate authority."}</p>${r.children.map((g:any)=>`<section class="authorization-child"><h3>${escape(g.supplier_name)} · ${g.purchase_order_id?'PO #'+g.purchase_order_id:'Confirmation request'}</h3><p>${escape(g.status)}</p>${g.kind==='REQUEST'&&this.context.quotation?`<button type="button" data-open-quotation="${g.id}">Open quotation workflow</button>`:''}${g.kind==='PO'&&this.context.receive?`<button type="button" data-receive-po="${g.purchase_order_id}">Receive</button>`:''}<p data-delivery-state="${g.id}"></p><button type="button" data-generate-documents="${g.id}">Prepare immutable vendor files</button><div data-documents="${g.id}"></div></section>`).join('')}`);this.dialog.querySelectorAll<HTMLButtonElement>('[data-open-quotation]').forEach(button=>button.onclick=async()=>{try{this.dialog.close();await this.context.quotation!(button.dataset.openQuotation!);}catch(error){this.context.notify((error as Error).message,true);}});this.dialog.querySelectorAll<HTMLButtonElement>('[data-receive-po]').forEach(button=>button.onclick=async()=>{try{this.dialog.close();await this.context.receive!(Number(button.dataset.receivePo));}catch(error){this.context.notify((error as Error).message,true);}});for(const g of r.children)void this.status(g.id);this.dialog.querySelectorAll<HTMLButtonElement>('[data-generate-documents]').forEach(button=>button.onclick=async()=>{button.disabled=true;const id=button.dataset.generateDocuments!,target=this.dialog.querySelector<HTMLElement>(`[data-documents="${id}"]`)!;try{await this.context.api('/api/vendor-authorizations/'+id+'/documents',{},120000);await this.status(id);}catch(error){target.textContent='Files not confirmed ready; the purchasing commitment remains recorded. '+(error as Error).message;}finally{button.disabled=false;}});}
 private async status(id:string){try{const d=await this.context.api('/api/vendor-authorizations/'+id),target=this.dialog.querySelector<HTMLElement>(`[data-documents="${id}"]`),status=this.dialog.querySelector<HTMLElement>(`[data-delivery-state="${id}"]`);if(!target||!status)return;target.innerHTML=d.artifacts.map((f:any)=>`<a href="/api/vendor-artifacts/${f.id}" download>${escape(f.format)} original</a>`).join(' · ');const delivery=d.commands.find((c:any)=>c.kind==='DELIVER_DOCUMENTS');const auto=d.kind==='PO'?d.snapshot.supplier.automatic_po_email:d.snapshot.supplier.automatic_spreadsheet_email;if(delivery?.state==='AMBIGUOUS')status.textContent='Delivery outcome uncertain. Reconcile the existing command; do not create or send another purchasing order.';else if(delivery?.state==='ACKNOWLEDGED')status.textContent='Simulated provider acceptance recorded for this command. No real delivery occurred and inbox delivery is not proven.';else status.textContent=auto?'Automatic delivery is pending separately; real delivery is disabled in this isolated phase.':'Automatic delivery is disabled. Vendor files are available for manual download when prepared.';}catch(error){this.context.notify('Recorded purchasing state is preserved; delivery status could not be loaded. '+(error as Error).message,true);}}
 async showRecorded(result:any){try{await this.context.refresh();}catch(error){this.context.notify('Authorization is recorded; refresh the worksheet before editing. '+(error as Error).message,true);}this.result(result);}
 async history(){await this.recover();const rows=await this.context.api('/api/purchase-authorizations');this.open('Recorded purchasing authorizations',rows.length?rows.map((r:any)=>`<button type="button" class="purchase-history" data-authorization="${r.id}">${escape(r.created_at)} · ${r.result.commitments_created} POs · ${r.result.requests_created} requests</button>`).join(''):'No purchasing authorizations recorded.');this.dialog.querySelectorAll<HTMLButtonElement>('[data-authorization]').forEach(button=>button.onclick=()=>this.result(rows.find((r:any)=>r.id===button.dataset.authorization).result));}
}
